extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var bullet_scene: PackedScene = load("res://bullet.tscn")
	if not check("exists", bullet_scene != null, "bullet.tscn deve caricarsi correttamente"):
		return
	var b := bullet_scene.instantiate() as Area2D
	var main := await instantiate_main_scene()
	main.add_child(b)
	b.global_position = Vector2(100, 100)
	await wait_seconds(2.2)
	check("timer_cleanup", not is_instance_valid(b), "Dopo il tempo di sopravvivenza (2s) il proiettile deve essere stato rimosso con queue_free()")

